// Question 3
function ajouter_personne($nom, $prenom, $age) {

  if(empty($nom) || empty($prenom) || empty($age)) return false;
  global $filename;
  $file = fopen($filename, 'a') or die("Unable to open the file $filename");
  $newLine = "$nom,$prenom,$age\n";
  fwrite($file, $newLine);
  fclose($file);
}

